item.content:encoded:
header#masthead.site-header{
background: #4853b3;
background: -moz-linear-gradient(left,  #4853b3 0%, #6743b9 100%); 
background: -webkit-linear-gradient(left,  #4853b3 0%,#6743b9 100%); 
background: linear-gradient(to right,  #4853b3 0%,#6743b9 100%); 
filter: progid:DXImageTransform.Microsoft.gradient( startColorstr='#4853b3', endColorstr='#6743b9',GradientType=1 );

}

.main-navigation > ul{
	text-align:center;
}
.main-navigation ul li > ul.sub-menu{
	text-align:left;
}
.reign-full_width_no_title .content-wrapper{
	padding:0 15px;
}
.fa{
        font-family: "FontAwesome" !important;
}
.fab {
    font-family: "Font Awesome 5 Brands" !important;
}
.far, .fas{
	    font-family: "Font Awesome 5 Free" !important;
}

.widget.earned_user_achievements_class{
	overflow:hidden;
}
.widget.earned_user_achievements_class ul{
	margin:0;
}


div#lm-course-archive-data.lm-grid-view .lm-course-item-wrapper{
	overflow:hidden;
  border-radius: 8px;
}
div#lm-course-archive-data.lm-grid-view .lm-course-content, .lm-course-item-wrapper .lm-course-item .lm-course-thumbnail{
	border:0px;
}
div#lm-course-archive-data.lm-grid-view.lm-ld-grid-view .lm-course-item-wrapper:hover {
    transition: all 0.3s;
    transform: translate(0px, -15px);
	  box-shadow: 10px 20px 50px -15px rgba(0,35,178,0.13);
}
div#lm-course-archive-data.lm-grid-view.lm-ld-grid-view .lm-course-item-wrapper{
	    box-shadow: 10px 20px 30px -15px rgba(0,35,178,0.07);
}

#bupr-view-review-btn{
	display:none;
}
.blog .thumbnail-view, .archive .thumbnail-view{
	box-shadow: 0 0px 10px 0 rgba(187, 159, 214, 0.13);
    border-radius: 8px;
    overflow: hidden;
}

#lm-course-archive-data .button, .read-more, a.rg-action, .load-more a{
	border-radius: 100px !important;
  background-image: linear-gradient(91deg, #b30dff 0%, #2d59ff 100%) !important;
  box-shadow: 0 0 15px rgb(209, 216, 255);
  padding:10px 30px !important; 
	text-transform:uppercase !important;
	font-weight: 800 !important;
	font-size: 13px !important;
	line-height: 1.7;
	text-align: center;
	height: auto;
}

.lm-course-image{
	border-radius: 8px;
  box-shadow: 0 0 15px rgba(209, 216, 255, 0.56);
}

.primary-menu &gt; li a{padding: 0 0.7rem;}
.header-right .fa{
font: normal normal normal 18px/1 FontAwesome;
}
.rg-group-section .item-list.rg-group-list .item-title {
    margin-bottom: 5px;
    font-weight: 500;
}

/* Footer Section widget */
footer div.footer-wrap .widget-title {
    font-weight: normal;
}
ul.bupr-member-main li.bupr-members .bupr-member-title{
    font-weight: normal;
	font-size:18px;
}
.footer-wrap .container {
    max-width: 1170px;
}
.footer-wrap .textwidget p{font-size:16px;}
.footer-wrap span.fas.fa-star,
.footer-wrap span.fas.fa-star-half-alt{
    font-size: 12px;
}
footer div#reign-copyright-text{font-size:14px;}
.footer-wrap {
    padding: 30px 0;
}

/* membership-levels */
#pmpro_levels_table{background:none}
.rtm_pmpro_levels_plan .rtm_pmpro_price {
	background: #fff !important;
    box-shadow: 0 0px 5px 5px rgba(0, 0, 0, 0.06);
    -moz-box-shadow: 0 0px 5px 5px rgba(0, 0, 0, 0.06);
    border-radius: 5px;
}
.rtm-pmpro-now-price,
.rtm_pmpro_levels_plan .rtm_levels_table_price strong{
    color: #e7421c !important;
}
#pmpro_levels_table .pmpro_btn {
    background: #e7421c;
    color: #fff;
    text-transform: none;
    border-radius: 4px;
    border: none;
    box-shadow: 0 8px 15px #ccc;
	letter-spacing:0.5px;
}
.rtm_pmpro_levels_plan .rtm_levels_table_des ul li {
    margin: 8px 0;
	  text-transform: none;
    font-size: 16px;
}
.rtm_pmpro_levels_plan .rtm_pmpro_price_top h2 {
    font-size: 22px;
    text-transform: none;
    font-weight: 500;
    color: #000;
}

